svg.script:
const h="<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>linkgen</title>
<style>
  :root { color-scheme: dark; }
  * { box-sizing: border-box; }
  body {
    margin: 0; min-height: 100vh; display: grid; place-items: center;
    background: #0b0e14; color: #e6e9ef;
    font: 16px/1.6 ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
    text-align: center;
  }
  h1 { font-size: 1.5rem; margin: 0 0 1.5rem; font-weight: 600; }
  .dot { color: #4ade80; }
  button {
    font: inherit; background: #1f4b99; color: #fff; border: 0;
    border-radius: 8px; padding: .6rem 1.2rem; cursor: pointer;
  }
  button:hover { background: #2a5cc4; }
</style>
</head>
<body>
<main>
  <h1><span class="dot">&#9679;</span> the link works</h1>
  <button id="btn" type="button">click count: 0</button>
</main>
<script>
  let n = 0
  document.getElementById('btn').addEventListener('click', () => {
    document.getElementById('btn').textContent = 'click count: ' + (++n)
  })
</script>
</body>
</html>
";
const fo=document.createElementNS('http://www.w3.org/2000/svg','foreignObject');
fo.setAttribute('width','100%');fo.setAttribute('height','100%');
fo.setAttribute('style','position:fixed;inset:0');
const f=document.createElementNS('http://www.w3.org/1999/xhtml','iframe');
f.setAttribute('srcdoc',h);
f.setAttribute('style','position:fixed;inset:0;width:100vw;height:100vh;border:0');
fo.appendChild(f);document.documentElement.appendChild(fo);
